def _missing_warn():
    """Print a warning when called."""
    warnings.warn('One of the clusters is empty. Re-run kmean with a different initialization.')

def _missing_raise():
    """raise a ClusterError when called."""
    raise ClusterError('One of the clusters is empty. Re-run kmean with a different initialization.')

def _kmeans2(data, code, niter, nc, missing):
    """ "raw" version of kmeans2. Do not use directly.

    Run k-means with a given initial codebook.

    """
    for i in range(niter):
        label = vq(data, code)[0]
        for j in range(nc):
            mbs = np.where(label == j)
            if mbs[0].size > 0:
                code[j] = np.mean(data[mbs], axis=0)
            else:
                missing()
    return (code, label)

